               q.y * qc_state.previous.y + q.z * qc_state.previous.z;
        dot = fabs(sdot);
        if (sdot < 0.0) {
            q.w = -q.w;
            q.x = -q.x;
            q.y = -q.y;
            q.z = -q.z;
